<script setup lang="ts">import {ref} from 'vue';import type{UserProfile}from '../api/client';const props=defineProps<{profile:UserProfile;busy:boolean}>();const emit=defineEmits<{save:[nickname:string,grade:number]}>();const nickname=ref(props.profile.nickname),grade=ref(props.profile.grade??1);</script>
<template><form class="card" @submit.prevent="emit('save',nickname,grade)"><label for="profileNickname">昵称</label><input id="profileNickname" v-model="nickname" maxlength="64" required><label for="profileGrade">当前年级</label><select id="profileGrade" v-model.number="grade"><option v-for="n in [1,2,3]" :key="n" :value="n">{{n}}年级</option></select><p class="muted">修改年级后，旧练习和成绩仍保留。</p><button class="primary" :disabled="busy">保存资料</button></form></template>
